(function() {
  const isReactNativeWebView = !!window.ReactNativeWebView;
  const originalPostMessage = window.postMessage;

  window.postMessage = function(data, targetOrigin, transfer) {
    if (isReactNativeWebView && 
        typeof data === 'string' && 
        data.match(/^setImmediate[\$#]/)) {
      originalPostMessage.call(this, data, targetOrigin, transfer);
    } else if (isReactNativeWebView) {
      window.ReactNativeWebView.postMessage(JSON.stringify(data));
    } else {
      originalPostMessage.call(this, data, targetOrigin, transfer);
    }
  };

  // 使用微任务优先的回退方案
  try {
    window.setImmediate = function(callback) {
      if (typeof queueMicrotask === 'function') {
        queueMicrotask(callback);
      } else if (typeof Promise === 'function') {
        Promise.resolve().then(callback);
      } else {
        setTimeout(callback, 0);
      }
    };
  } catch(error) {
    console.log("[setImmediate]", error)
  }

  // 监听hash的改变,并通知RN
  window.addEventListener('hashchange', function() {
    window.ReactNativeWebView.postMessage(JSON.stringify({
      functionName: "ROUTE_CHANGE",
      params: JSON.stringify({path: window.location.hash}),
    }));
  });

  // iOS必须返回true
  true;
})();
